import{_ as t,o,c as d,a2 as r}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"当前交付状态","description":"2026-11-23 的代码、自动测试、构建和明确留空项。","frontmatter":{"title":"当前交付状态","description":"2026-11-23 的代码、自动测试、构建和明确留空项。","outline":[2,3]},"headers":[],"relativePath":"delivery/status.md","filePath":"delivery/status.md","lastUpdated":1795427057000}'),n={name:"delivery/status.md"};function c(a,e,l,i,s,u){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="当前交付状态" tabindex="-1">当前交付状态 <a class="header-anchor" href="#当前交付状态" aria-label="Permalink to &quot;当前交付状态&quot;">​</a></h1><p>核对日期：2026-11-23，目标版本 <code>0.3.4</code>。本文只写当前 <code>main</code> 代码和本机能复现的事实，不把页面存在当成闭环，也不把历史计划当成现状。</p><blockquote><p>阶段二至六的路线页是历史计划，部分描述已被当前范围收缩取代。当前范围以本文和<a href="/hearth-os/delivery/acceptance-2026-11.html">2026-11 验收报告</a>为准。</p></blockquote><h2 id="这一版做了什么" tabindex="-1">这一版做了什么 <a class="header-anchor" href="#这一版做了什么" aria-label="Permalink to &quot;这一版做了什么&quot;">​</a></h2><ul><li><strong>运行时稳定：</strong> 工具副作用拆成业务结算与物理清理两条账；<code>settled</code> 不再等于“已经清干净”，终态 run 会真正终止已登记的 shell 进程并把 <code>confirmed / failed</code> 写回 <code>run_operations</code>。恢复闸门沿父 run 链检查 prepared/dispatched 操作、运行中后台进程和 checkpoint proof，未知副作用不再自动重放。</li><li><strong>单一事实源：</strong> 服务端不再写 JSONL journal，消息、工具结算、检查点和 run 边界统一写入 SQLite <code>events</code>（schema v40）；checkpoint 文件降级为物化视图，损坏时从事件按 <code>event_seq</code> 回放重建。</li><li><strong>宿主生命周期：</strong> <code>HostKernel</code> 持有数据目录的唯一租约，按 <code>lease → store → operations → runs → tasks → background → ready</code> 推进；恢复完成前 <code>/api/ready</code> 返回 503，任务写路由返回 <code>HOST_NOT_READY</code>。</li><li><strong>Windows 原生沙箱：</strong> <code>hearth-native.exe</code> 用 AppContainer package SID、workspace/temp ACL、kill-on-close Job Object 和父进程 watchdog 启动子进程；网络只支持 <code>deny | open</code>，声明域名白名单或 helper 缺失时 fail-closed。</li><li><strong>交互式 shell 与后台进程：</strong> <code>shell</code> 支持 <code>pty: true</code> 与 <code>cols</code> / <code>rows</code>，经 ConPTY 在 AppContainer 内运行；<code>shell_input</code> / <code>shell_resize</code> 可输入与调整；每个会话写入 SQLite <code>background_processes</code>，重启时按 PID + 创建时间判定，活的杀进程树、复用的只标 <code>lost</code>。</li><li><strong>证据与回收：</strong> 每个终态 run 输出 <code>run-evidence.json</code>；长跑矩阵从 12 扩到 18 个崩溃点，各重复 3 次；新增 <code>npm run storage:prune</code> 预演式回收旧 run 与未引用工具输出。</li><li><strong>界面收缩：</strong> 任务列表、任务详情和“需要你”收件箱页面已下线，执行轨迹改为对话内联运行卡；主导航为聊天、资料库、Context，邮件/定时任务/连接收在“更多”。</li></ul><h2 id="自动验证" tabindex="-1">自动验证 <a class="header-anchor" href="#自动验证" aria-label="Permalink to &quot;自动验证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>命令</th><th>结果</th></tr></thead><tbody><tr><td>版本一致</td><td><code>npm run version:check</code></td><td>0.3.4：7 个 workspace + Cargo + Tauri + lockfile</td></tr><tr><td>类型检查</td><td><code>npm run typecheck</code></td><td>0 错误</td></tr><tr><td>单元/集成测试</td><td><code>npm test</code></td><td>140 个文件、946 个用例（931 通过、15 跳过、0 失败）</td></tr><tr><td>长跑矩阵</td><td><code>npm run test:longrun</code></td><td>18/18 通过</td></tr><tr><td>Web 构建</td><td><code>npm run build</code></td><td>通过（JS 643.06 kB / CSS 158.97 kB）</td></tr><tr><td>文档构建</td><td><code>npm run docs:build</code></td><td>通过</td></tr><tr><td>首跑离线自检</td><td><code>npm run first:run -- --fake</code></td><td>通过（只验证脚本与任务链路，不代表模型可用）</td></tr><tr><td>0.3.4 安装包</td><td><code>npm run release:build</code></td><td>NSIS 安装包 30.5 MiB、便携 zip 47.2 MiB；以 GitHub Pre-release 发布</td></tr><tr><td>Windows 沙箱</td><td><code>npm run test:sandbox</code></td><td>12 项真实测试：越界写、只读、junction 逃逸、密钥过滤、网络拒绝、PTY 与 Job 关闭</td></tr></tbody></table><blockquote><p>说明：Windows 本地跑 <code>npm test</code> 时，worktrees/subagents/沙箱等真实进程测试较慢；<code>vitest.config.ts</code> 将单测超时设为 20 秒、hook 超时设为 30 秒。上表为 2026-11-23 在本机 <code>main</code> 工作树上实际复跑的结果。0.2.0 与 0.3.3 的验收快照仍保留在 <a href="/hearth-os/delivery/acceptance-2026-11.html">2026-11 验收报告</a>，作为历史记录不再改写。</p></blockquote><h2 id="仍然明确留空" tabindex="-1">仍然明确留空 <a class="header-anchor" href="#仍然明确留空" aria-label="Permalink to &quot;仍然明确留空&quot;">​</a></h2><ul><li><strong>自动更新签名未发布：</strong> 仓库没有更新签名私钥、公钥和发布地址；0.3.4 安装包不包含自动更新产物。</li><li><strong>Windows 代码签名未处理：</strong> 没有 Authenticode 证书，安装包首次运行可能触发 SmartScreen。</li><li><strong>干净机安装/卸载未验收：</strong> 0.3.4 已在开发机完成安装包全新安装与启动验证，但未在全新 Windows 用户环境执行卸载、旧版本升级和企业策略检查。</li><li><strong>真实模型首跑未验收：</strong> 仍取决于本机模型配置和供应商权限；没有可用 key 时只能用 <code>first:run --fake</code> 验证脚本自身。</li><li><strong>日常 Chrome 扩展桥未实现：</strong> 目前使用独立 Chrome profile，首次需要在该 profile 里登录站点；Chrome 136+ 默认 profile 禁止远程调试。</li><li><strong>真实账户未验收：</strong> 飞书租户、SMTP/IMAP 账户、桌面设备仍只有代码和本地测试闭环。</li><li><strong>长期崩溃恢复未做真实演练：</strong> 18 个崩溃点由自动化长跑矩阵覆盖，但没有数周真实使用中的断电、蓝屏和强制结束进程记录。</li><li><strong>清理覆盖面有限：</strong> cleanup 目前对已登记 shell 进程执行真实终止；subagent/worktree/browser 等资源暂无清理 handler 时会明确记 <code>failed</code> 并留下原因。</li></ul><h2 id="已移出当前范围" tabindex="-1">已移出当前范围 <a class="header-anchor" href="#已移出当前范围" aria-label="Permalink to &quot;已移出当前范围&quot;">​</a></h2><ul><li>任务列表、任务详情和“需要你”收件箱页面；</li><li>任务模板系统；</li><li>主动服务、注意力预算、常驻意图和预置动作集群；</li><li>Goal contract 与自动完成判定；</li><li>方法学习与任务绑定；</li><li>多设备同步、远程节点和执行器插件市场。</li></ul><p>这些能力如重新引入，需要单独设计和验收，不能从历史文档直接推断为“已可用”。</p>',13)])])}const g=t(n,[["render",c]]);export{p as __pageData,g as default};
